from pathlib import Path
sys.path.insert(0, "/app/tools")
import replay as R

SINCE = "2027-05-03T14:00:05.000Z"
FIXES = {
    "utm": ("keys.py", "        if name in cfg.ignore_params:", "        if name in cfg.ignore_params or name.startswith('utm_'):"),
    "locale": ("locale.py", "                return rng\n", "                return loc\n"),
    "purge": ("cache.py", 'prefix = f"{route}|{ident}"', 'prefix = f"{route}|{ident}|"'),
    "ttl": ("config.py", "        return int(value)\n", "        return int(value) * 1000\n"),
}
EXTRA = {}
if len(sys.argv) > 1:
    pass


def run(pkgdir):
    for m in [m for m in sys.modules if m.startswith("shelfmark")]:
        del sys.modules[m]
    sys.path[:] = [p for p in sys.path if not p.startswith("/tmp/pkg")]
    out = io.StringIO()
    R.replay(Path("/app"), Path(pkgdir), SINCE, None, False, out)
    res = {}
    for line in out.getvalue().splitlines():
        if line.startswith("#"):
            continue
        p = line.split()
        res[p[0]] = (p[-2].split("=")[1], p[-1].split("=")[1], p[3])
    return res


def make(name, fixes):
    d = Path("/tmp/pkg_" + name)
    if d.exists():
        shutil.rmtree(d)
    d.mkdir()
    shutil.copytree("/app/shelfmark", d / "shelfmark")
    for f in fixes:
        fn, old, new = FIXES[f]
        p = d / "shelfmark" / fn
        t = p.read_text()
        assert t.count(old) == 1, f
        p.write_text(t.replace(old, new))
    return d


if __name__ == "__main__":
    names = sys.argv[1:] or list(FIXES)
    for n in names:
        fx = n.split("+")
        res = run(make(n.replace("+", "_"), fx))
        ch = [(rid, v) for rid, v in res.items() if v[0] == "miss" and v[1] == "hit"]
        bad = [(rid, v) for rid, v in res.items() if v[0] == "hit" and v[1] == "miss"]
        print(n, "miss->hit", len(ch), "first", ch[0][0] if ch else None, "hit->miss", len(bad))
"}

